const added = document.querySelector('#additional-sections');
added.innerHTML = `
<section class="story-split wrap section" id="findings"><div><p class="eyebrow">02 / THE FINDING THAT CHANGES THE BRIEF</p><h2>This is not<br>a new surge.</h2><p>All six selected parks recorded fewer visits in 2025 than in 2024. The planning opportunity is to distribute visits more thoughtfully—not assume demand is accelerating everywhere.</p><p>Among the five parks open throughout both years, visits fell <strong id="combined-change"></strong>. Rockin’ River Ranch is excluded from that comparison because it opened in February 2024.</p><p class="source"><a href="methods.html#visitation">Calculated from the two annual attendance tables ↗</a></p></div><div class="chart-frame"><h3>Year-over-year change in park visits</h3><p class="small">2025 versus 2024 · five comparable full-year sites</p><div id="change-bars"></div><p class="small">A decline does not explain its cause. Two years cannot establish a long-term trend.</p></div></section>
<section class="explorer-band" id="destinations"><div class="wrap section"><div class="section-heading"><div><p class="eyebrow">03 / CHOOSE A PLACE AND A MOMENT</p><h2>Four sites.<br>Three neighboring communities.</h2></div><p>Compare a potential side trip with Slide Rock’s seasonal pattern. These are selected attractions, not a census of all destinations or total city visitation.</p></div><div class="controls"><label>Destination<select id="destination"><option value="dead">Cottonwood · Dead Horse Ranch</option><option value="jerome">Jerome · State Historic Park</option><option value="fort">Camp Verde · Fort Verde</option><option value="rockin">Camp Verde · Rockin’ River Ranch</option></select></label><label>Month to examine<select id="month">${months.map((m,i)=>`<option value="${i}" ${i===8?'selected':''}>${m}</option>`).join('')}</select></label></div><div class="destination-layout"><article class="destination-detail" id="destination-detail" aria-live="polite"></article><div class="chart-frame"><div class="chart-title"><h3>Different seasonal rhythms</h3><span class="small">2025 · share of annual visits</span></div><div id="season-chart"></div><div id="line-legend" class="legend"></div><p class="small">Each line sums to 100% across the year. This compares timing, not crowding or capacity.</p><details><summary>Read the monthly chart as a table</summary><div id="line-table" class="table-scroll"></div></details></div></div><p class="source">Visitation: Arizona State Parks / NAU. Destination descriptions: official park pages. </p></div></section>
<section class="wrap section" id="economy"><div class="section-heading"><div><p class="eyebrow">04 / THE ECONOMIC REASON TO EXPLORE</p><h2>A park visit can support<br>a wider local trip.</h2></div><p>Published estimates associate nearby park visits with spending on accommodation, meals, retail, and transport. They describe existing economic activity, not new revenue a campaign would create.</p></div><div class="chart-frame"><div class="chart-title"><h3>Spending associated with the four candidate parks</h3><label class="inline-label">Category<select id="spend-category"><option value="total">All spending</option><option>Food and beverage</option><option>Lodging</option><option>Retail</option><option>Camping</option></select></label></div><p class="small">2025 nominal US dollars · estimated non-local visitor spending within 50 miles of each park</p><div id="spend-bars"></div></div><p class="source">Source: University of Arizona, 2025 Economic Contributions & Impacts of Arizona State Parks (June 2026), Table 44. <a href="methods.html#spending">Method & report ↗</a></p><div class="insight"><span>KEEP THE SCALE HONEST</span><p>These spending areas overlap and can include Sedona itself. Do not add the bars into a “new money” total, assign the full amount to the host town, or turn them into a forecast.</p></div><div class="context-grid"><article><p class="eyebrow">ACCOMMODATION CONTEXT</p><h3>Hotel demand changes with the season, too.</h3><p>Sedona+ hotel occupancy rose from 59.6% in August to 74.8% in October 2025. The Village of Oak Creek+ market rose from 60.1% to 71.9%.</p><div id="lodging-table" class="table-scroll"></div><p class="source">STR, published by the City of Sedona, October 2025 report, p. 4. ADR = average daily room rate in USD. Reporting samples and market boundaries differ; a June hotel closure affected Sedona+ supply. <a href="methods.html#lodging">Source and coverage ↗</a></p></article><article class="plain-note"><p class="eyebrow">WHAT WE STILL NEED</p><h3>A room is not available just because a park is quiet.</h3><p>Comparable room inventory and occupancy for Cottonwood, Jerome, and Camp Verde were not verified. Their accommodation capacity remains unknown.</p><p>Use these hotel figures as context for the gateway area. Confirm rooms, group availability, staffing, and local access before committing to a campaign.</p></article></div></section>
<section class="resident-band" id="residents"><div class="wrap section story-split"><div><p class="eyebrow">05 / THE COMMUNITY TEST</p><h2>Tourism promotion<br>needs a local mandate.</h2><p>In Sedona’s 2024 survey, only 6% wanted tourism to play a larger role in the economy. That supports a careful conversation about management; it does not demonstrate support for any particular redistribution policy.</p><p>We have no comparable resident survey for the receiving communities in this dataset. Their support must be established separately.</p></div><div><h3>Preferred future role of tourism</h3><p class="small">City of Sedona · 2024 weighted survey percentages</p><div id="resident-bars"></div><p class="small">551 survey respondents overall · 20% response rate · reported overall margin of error up to ±4 percentage points at 95% confidence. The tourism-question sample size is not separately reported here.</p><p class="source"><a href="methods.html#residents">National Community Survey, methods pp. 2–6; question results p. 30 ↗</a></p></div></div></section>
<section class="wrap section" id="recommendations"><div class="section-heading"><div><p class="eyebrow">06 / THE DECISION</p><h2>Start small.<br>Choose the season deliberately.</h2></div><p>These are proposed pilots, not a numerical ranking. Each balances the observed seasonal pattern with the kind of experience offered and the evidence still missing.</p></div><div class="recommendation-grid"><article><span class="recommendation-number">01</span><p class="eyebrow">COTTONWOOD / FIRST PILOT</p><h3>Test a September nature-and-town itinerary.</h3><p>Dead Horse Ranch recorded 11,705 September visits in 2025—51% of its March peak—while Slide Rock remained at 64% of its own peak. Pair a short park visit with Cottonwood businesses, subject to weather and capacity checks.</p><p><strong>Why this place:</strong> a substantial existing visitor base and a verified Sedona–Cottonwood bus connection. The bus does not establish direct park access; solve the last leg first.</p><p><strong>Before promotion:</strong> agree on access, parking and operating limits with local partners, and verify accommodation. September can still be hot.</p><a href="https://verdeshuttle.com/routes/verde-shuttle/" target="_blank" rel="noopener">Check the transport connection ↗</a></article><article><span class="recommendation-number">02</span><p class="eyebrow">JEROME / CULTURAL ALTERNATIVE</p><h3>Test a modest summer museum side trip.</h3><p>Jerome State Historic Park received 16.5% of annual visits in June–August, compared with 34.9% at Slide Rock. The Douglas Mansion museum offers a different experience for visitors interested in history.</p><p><strong>Why this season:</strong> the observed timing differs from Slide Rock’s. Test interest rather than assume swimmers want a museum visit.</p><p><strong>Before promotion:</strong> check indoor comfort, parking, road access and resident support. Low park counts say nothing about crowding elsewhere in Jerome.</p><a href="https://azstateparks.com/jerome" target="_blank" rel="noopener">Official museum and access information ↗</a></article><article><span class="recommendation-number">03</span><p class="eyebrow">CAMP VERDE / SMALLER TEST</p><h3>Try history outside Fort Verde’s October peak.</h3><p>Fort Verde’s September count was 524, versus 1,461 in October 2025. Consider a small September or November history itinerary after checking events and opening hours.</p><p><strong>Keep Rockin’ River Ranch conditional:</strong> its 5,672 annual visits are not proof of excess capacity. It opened in 2024 and currently advertises Friday–Sunday operation.</p><p><strong>Before promotion:</strong> agree on group size, interpretation and community priorities. Treat the two parks as distinct experiences.</p><a href="https://azstateparks.com/fort-verde" target="_blank" rel="noopener">Official park and event information ↗</a></article></div><p class="source">Seasonal comparisons calculated from the 2025 attendance table. <a href="methods.html#recommendations">Recommendation logic and operational sources ↗</a></p><div class="pilot"><p class="eyebrow">HOW TO KNOW IF IT WORKS</p><h3>Measure the pilot before expanding it.</h3><p>Track itinerary uptake, business participation, aggregate visitor feedback, parking or queue conditions, and receiving-community sentiment. Compare equivalent days with a baseline and record weather and events. Ask whether the side trip replaced time in Sedona or simply extended the trip; counts alone cannot show that.</p></div></section>
`;
const destinationNotes={dead:{title:'Cottonwood',sub:'Dead Horse Ranch State Park',status:'First pilot · September',copy:'Nature, river scenery and a town visit can form one itinerary. Its spring peak suggests avoiding a blanket spring promotion.',access:'Verde Shuttle connects Sedona with central Cottonwood. Last-mile access to the park has not been verified.',limit:'No verified park carrying capacity or town hotel availability. A low month can reflect heat, weather or operating conditions.'},jerome:{title:'Jerome',sub:'Jerome State Historic Park',status:'Cultural pilot · Summer',copy:'The Douglas Mansion museum creates a history-focused alternative to water recreation. Summer visits are low relative to its own spring peak.',access:'Official park information lists daily museum hours. Driving times and direct public-transit access were not verified.',limit:'Park attendance does not capture visitors to the rest of Jerome. Confirm parking, indoor comfort, community support and visitor interest.'},fort:{title:'Camp Verde',sub:'Fort Verde State Historic Park',status:'Small pilot · September or November',copy:'A history itinerary could operate outside the park’s October peak. Event calendars need to inform the timing.',access:'The official park page lists daily opening and historic buildings. Direct public-transit access from Sedona was not verified.',limit:'Only 8,769 visits in 2025. Smaller scale does not establish staffing or group capacity; local resident sentiment is missing.'},rockin:{title:'Camp Verde',sub:'Rockin’ River Ranch State Park',status:'Conditional · confirm operations first',copy:'A newer nature-focused site deserves consideration, but restricted operating days explain part of its smaller scale.',access:'The official park page advertises Friday–Sunday, 9 a.m.–5 p.m., last entry 4 p.m. Recheck before planning.',limit:'Opened February 2024, so its first-year January zero is not weak demand. No measured carrying capacity or per-open-day visitor series.'}};
function bars(target,items,format,max){$(target).innerHTML=items.map(x=>`<div class="bar-row"><div class="bar-label"><span>${x.name}</span><strong>${format(x.value)}</strong></div><div class="bar-track"><div style="width:${Math.max(1,x.value/max*100)}%;background:${x.color||'#24594b'}"></div></div></div>`).join('')}
function renderChanges(){const ps=DATA.parks.filter(p=>p.id!=='rockin'),tot=y=>ps.reduce((s,p)=>s+p.visits[y].reduce((a,b)=>a+b,0),0);$('#combined-change').textContent=((1-tot(2025)/tot(2024))*100).toFixed(1)+'%';bars('#change-bars',ps.map(p=>({name:p.name,value:(1-p.visits[2025].reduce((a,b)=>a+b,0)/p.visits[2024].reduce((a,b)=>a+b,0))*100,color:'#a34629'})),v=>'−'+v.toFixed(1)+'%',12)}
function renderDestination(){const p=DATA.parks.find(p=>p.id===$('#destination').value),ref=DATA.parks[0],m=+$('#month').value,n=destinationNotes[p.id],a=p.visits[2025],peak=Math.max(...a);$('#destination-detail').innerHTML=`<p class="pill">${n.status}</p><h3>${n.title}</h3><p class="destination-sub">${n.sub}</p><div class="month-stat"><strong>${fmt(a[m])}</strong><span>${months[m]} 2025 park visits<br>${Math.round(a[m]/peak*100)}% of this park’s busiest month</span></div><p>${n.copy}</p><dl><dt>Access evidence</dt><dd>${n.access}</dd><dt>What limits the choice</dt><dd>${n.limit}</dd></dl><a href="${p.url}" target="_blank" rel="noopener">Official park information ↗</a>`;const W=660,H=280,left=42,right=18,top=20,bottom=40;const x=i=>left+i*(W-left-right)/11,y=v=>H-bottom-v/20*(H-top-bottom);const series=[ref,p].map(q=>{const sum=q.visits[2025].reduce((a,b)=>a+b,0);return {p:q,vals:q.visits[2025].map(v=>v/sum*100)}});$('#season-chart').innerHTML=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Monthly share of annual park visits in 2025: Slide Rock and ${p.name}. A data table follows.">${[0,5,10,15,20].map(v=>`<line x1="${left}" y1="${y(v)}" x2="${W-right}" y2="${y(v)}" stroke="#d7ddd5"/><text x="${left-10}" y="${y(v)+4}" text-anchor="end" fill="#5a665f" font-size="12">${v}%</text>`).join('')}<rect x="${x(m)-12}" y="${top}" width="24" height="${H-top-bottom}" fill="#efb383" opacity=".23"/>${months.map((v,i)=>`<text x="${x(i)}" y="${H-15}" text-anchor="middle" font-size="12" fill="#5a665f">${v}</text>`).join('')}${series.map(s=>`<polyline points="${s.vals.map((v,i)=>`${x(i)},${y(v)}`).join(' ')}" fill="none" stroke="${s.p.color}" stroke-width="3" ${s.p.id==='slide'?'stroke-dasharray="6 4"':''}/>${s.vals.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="${m===i?6:3}" fill="${s.p.color}"><title>${s.p.name}, ${months[i]}: ${v.toFixed(1)}% of annual visits</title></circle>`).join('')}`).join('')}</svg>`;$('#line-legend').innerHTML=series.map(s=>`<span><i style="background:${s.p.color}"></i>${s.p.name}${s.p.id==='slide'?' (dashed)':''}</span>`).join('');$('#line-table').innerHTML=`<table class="data-table"><thead><tr><th>Month</th>${series.map(s=>`<th>${s.p.name}</th>`).join('')}</tr></thead><tbody>${months.map((mo,i)=>`<tr><th>${mo}</th>${series.map(s=>`<td>${s.vals[i].toFixed(1)}%</td>`).join('')}</tr>`).join('')}</tbody></table>`}
function renderSpend(){const cat=$('#spend-category').value;const items=DATA.parks.filter(p=>p.role==='Candidate').map(p=>({name:p.name,value:cat==='total'?p.directSpending:p.spending[cat],color:p.color}));bars('#spend-bars',items,v=>'$'+(v/1e6).toFixed(v>=1e6?2:3)+'M',Math.max(...items.map(x=>x.value)))}
function renderContext(){bars('#resident-bars',DATA.residents.map((r,i)=>({name:r.response,value:r.percent,color:['#edb183','#b0c5b1','#729680'][i]})),v=>v+'%',100);$('#lodging-table').innerHTML=`<table class="data-table"><thead><tr><th>2025</th><th>Sedona+<br>Occ. / ADR</th><th>Oak Creek+<br>Occ. / ADR</th></tr></thead><tbody>${[8,9,10].map(m=>`<tr><th>${months[m-1]}</th>${['Sedona+','Village of Oak Creek+'].map(g=>{const r=DATA.lodging.find(r=>r.month===m&&r.study_area===g);return `<td>${r.occupancy_pct}% / $${r.adr_usd}</td>`}).join('')}</tr>`).join('')}</tbody></table>`}
function initializeStory(){renderChanges();renderDestination();renderSpend();renderContext();['destination','month'].forEach(id=>$('#'+id).addEventListener('change',renderDestination));$('#spend-category').addEventListener('change',renderSpend);registerPlanningTool()}
function registerPlanningTool(){const context=document.modelContext;if(!context?.registerTool)return;const controller=new AbortController();window.addEventListener('pagehide',()=>controller.abort(),{once:true});try{Promise.resolve(context.registerTool({name:'configure_destination_comparison',title:'Compare a Verde Valley side trip',description:'Change the visible destination and month comparison for the 2025 park-visitation data. Does not book or promote a trip.',inputSchema:{type:'object',properties:{destination:{type:'string',enum:['dead','jerome','fort','rockin']},month:{type:'integer',minimum:1,maximum:12}},required:['destination','month'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!['dead','jerome','fort','rockin'].includes(input.destination)||!Number.isInteger(input.month)||input.month<1||input.month>12||Object.keys(input).some(k=>!['destination','month'].includes(k)))throw new Error('Choose a listed destination and an integer month from 1 to 12.');$('#destination').value=input.destination;$('#month').value=String(input.month-1);renderDestination();const p=DATA.parks.find(p=>p.id===input.destination);return {destination:p.fullName,month:months[input.month-1],year:2025,visits:p.visits[2025][input.month-1],capacity:'unknown'};}},{signal:controller.signal})).catch(()=>{});}catch{}}
